     1→/// Build configuration for Zig Compiler with RISC-V backend
     2→///
     3→/// Compile targets:
     4→/// - zig build: build compiler binary
     5→/// - zig build test: run all tests
     6→/// - zig build riscv_basic_test: run basic arithmetic tests
     7→/// - zig build riscv_function_test: run function/calling convention tests
     8→/// - zig build riscv_control_test: run control flow tests
     9→
    10→const std = @import("std");
    11→
    12→pub fn build(b: *std.Build) void {
    13→    const target = b.standardTargetOptions(.{});
    14→    const optimize = b.standardOptimizeOption(.{});
    15→
    16→    // ========================================================================
    17→    // Main Compiler Library
    18→    // ========================================================================
    19→
    20→    const riscv_codegen_lib = b.addStaticLibrary(.{
    21→        .name = "riscv_codegen",
    22→        .root_source_file = b.path("src/riscv_codegen.zig"),
    23→        .target = target,
    24→        .optimize = optimize,
    25→    });
    26→
    27→    const riscv_codegen_module = b.addModule("riscv_codegen", .{
    28→        .root_source_file = b.path("src/riscv_codegen.zig"),
    29→    });
    30→
    31→    // ========================================================================
    32→    // Step 1: Basic Arithmetic Tests (15 tests)
    33→    // ========================================================================
    34→
    35→    const riscv_basic_test_exe = b.addTest(.{
    36→        .root_source_file = b.path("test/riscv_basic_test.zig"),
    37→        .target = target,
    38→        .optimize = optimize,
    39→    });
    40→
    41→    riscv_basic_test_exe.root_module.addImport("riscv_codegen", riscv_codegen_module);
    42→
    43→    const run_riscv_basic_test = b.addRunArtifact(riscv_basic_test_exe);
    44→
    45→    const riscv_basic_test_step = b.step("riscv_basic_test", "Run RISC-V basic arithmetic tests (Step 1)");
    46→    riscv_basic_test_step.dependOn(&run_riscv_basic_test.step);
    47→
    48→    // ========================================================================
    49→    // Step 2: Function & Calling Convention Tests (12 tests)
    50→    // ========================================================================
    51→
    52→    const riscv_function_test_exe = b.addTest(.{
    53→        .root_source_file = b.path("test/riscv_function_test.zig"),
    54→        .target = target,
    55→        .optimize = optimize,
    56→    });
    57→
    58→    riscv_function_test_exe.root_module.addImport("riscv_codegen", riscv_codegen_module);
    59→
    60→    const run_riscv_function_test = b.addRunArtifact(riscv_function_test_exe);
    61→
    62→    const riscv_function_test_step = b.step("riscv_function_test", "Run RISC-V function tests (Step 2)");
    63→    riscv_function_test_step.dependOn(&run_riscv_function_test.step);
    64→
    65→    // ========================================================================
    66→    // Step 3: Control Flow Tests (13 tests)
    67→    // ========================================================================
    68→
    69→    const riscv_control_test_exe = b.addTest(.{
    70→        .root_source_file = b.path("test/riscv_control_test.zig"),
    71→        .target = target,
    72→        .optimize = optimize,
    73→    });
    74→
    75→    riscv_control_test_exe.root_module.addImport("riscv_codegen", riscv_codegen_module);
    76→
    77→    const run_riscv_control_test = b.addRunArtifact(riscv_control_test_exe);
    78→
    79→    const riscv_control_test_step = b.step("riscv_control_test", "Run RISC-V control flow tests (Step 3)");
    80→    riscv_control_test_step.dependOn(&run_riscv_control_test.step);
    81→
    82→    // ========================================================================
    83→    // Aggregate test step
    84→    // ========================================================================
    85→
    86→    const test_step = b.step("test", "Run all tests (40 total: 15+12+13)");
    87→    test_step.dependOn(riscv_basic_test_step);
    88→    test_step.dependOn(riscv_function_test_step);
    89→    test_step.dependOn(riscv_control_test_step);
    90→
    91→    // ========================================================================
    92→    // Main executable (compiler binary)
    93→    // ========================================================================
    94→
    95→    const exe = b.addExecutable(.{
    96→        .name = "zig-compiler",
    97→        .root_source_file = b.path("src/main.zig"),
    98→        .target = target,
    99→        .optimize = optimize,
   100→    });
   101→
   102→    exe.root_module.addImport("riscv_codegen", riscv_codegen_module);
   103→
   104→    b.installArtifact(exe);
   105→
   106→    const run_cmd = b.addRunArtifact(exe);
   107→    if (b.args) |args| {
   108→        run_cmd.addArgs(args);
   109→    }
   110→
   111→    const run_step = b.step("run", "Run the compiler");
   112→    run_step.dependOn(&run_cmd.step);
   113→
   114→    // ========================================================================
   115→    // Install step (builds and installs all artifacts)
   116→    // ========================================================================
   117→
   118→    const install_step = b.getInstallStep();
   119→}
